import type {
  Action, AgentRecord, AgentRoleName, Milestone, Mode, ReportedPhase, RunState, Stage, TaskEvent, TaskPhase, TaskState, Waiting,
} from '../types'
import { decisionsOf } from './ledger.ts'
import { isUncleanVerdict, parseReport } from './reports.ts'
import { currentTask, findTask } from './selectors.ts'

type ActionOf<T extends Action['type']> = Extract<Action, { type: T }>

const STAGES: readonly Stage[] = ['brainstorm', 'plan', 'exec', 'final-review', 'finishing', 'done']
const rank = (stage: Stage) => STAGES.indexOf(stage)

/** The TDD phases of a task, in their order: a segment never goes back to an earlier one. */
const TDD_PHASES = ['red', 'green', 'refactor'] as const
type TddPhase = typeof TDD_PHASES[number]
const TASK_PHASES: ReadonlySet<ReportedPhase> = new Set<ReportedPhase>(TDD_PHASES)
const tddRank = (phase: TaskPhase) => (TDD_PHASES as readonly TaskPhase[]).indexOf(phase)
/** Roles whose skills and TDD phases belong to their own work, not to the run's progress. */
const WORKER_ROLES: ReadonlySet<AgentRoleName> = new Set<AgentRoleName>(['implementer', 'reviewer', 're-reviewer', 'final-reviewer', 'builder-check'])

export function newRun(stage: Stage, at: number, mode?: Mode): RunState {
  return {
    id: `run-${at}`, startedAt: at, stage, stageStartedAt: { [stage]: at }, ...(mode ? { mode } : {}),
    tasks: [], milestones: [], agents: {}, decisions: [],
  }
}

// --- run helpers ---

function setStage(s: RunState, stage: Stage, at: number): RunState {
  if (stage === s.stage) return s
  const { stagePhase: _dropped, ...rest } = s
  return { ...rest, stage, stageStartedAt: { ...s.stageStartedAt, [stage]: at } }
}

const advance = (s: RunState, stage: Stage, at: number) => (rank(stage) > rank(s.stage) ? setStage(s, stage, at) : s)

function addMilestone(s: RunState, m: Milestone, supersedes?: (old: Milestone) => boolean): RunState {
  if (s.milestones.some(o => o.stage === m.stage && o.label === m.label)) return s
  const kept = supersedes ? s.milestones.filter(o => !supersedes(o)) : s.milestones
  return { ...s, milestones: [...kept, m] }
}

function withExecMilestone(s: RunState, at: number): RunState {
  if (s.stage !== 'exec' || !s.mode || s.milestones.some(m => m.stage === 'exec')) return s
  return addMilestone(s, { stage: 'exec', label: s.mode === 'sdd' ? 'exec SDD' : 'exec inline', at })
}

const setAgent = (s: RunState, id: string, rec: AgentRecord): RunState => ({ ...s, agents: { ...s.agents, [id]: rec } })

// --- task helpers ---


function ensureTask(s: RunState, n: string): RunState {
  if (findTask(s, n)) return s
  return { ...s, tasks: [...s.tasks, { n, title: '?', steps: 0, status: 'todo', fixRounds: 0, trail: [] }] }
}

/** Applies `f` to task `n` if it exists. */
function mapTask(s: RunState, n: string, f: (t: TaskState) => TaskState): RunState {
  if (!findTask(s, n)) return s
  return { ...s, tasks: s.tasks.map(t => (t.n === n ? f(t) : t)) }
}

/** Applies `f` to task `n`, adding it with an unknown title when the plan lacks it. */
const upsertTask = (s: RunState, n: string, f: (t: TaskState) => TaskState) => mapTask(ensureTask(s, n), n, f)

/** Appends `e`; an event that starts a segment drops the pending write of the previous one. */
function push(t: TaskState, e: TaskEvent): TaskState {
  if (!startsSegment(e)) return { ...t, trail: [...t.trail, e] }
  const { pendingWriteSegment: _stale, ...rest } = t
  return { ...rest, trail: [...t.trail, e] }
}

const activate = (t: TaskState, at: number): TaskState => ({ ...t, status: 'active', startedAt: t.startedAt ?? at, activeAt: at })

const finish = (t: TaskState, at: number): TaskState => ({ ...push(t, { phase: 'done', at }), status: 'done', doneAt: t.doneAt ?? at })

function fix(t: TaskState, at: number): TaskState {
  const round = t.fixRounds + 1
  return { ...push(t, { phase: 'fix', at, round }), fixRounds: round }
}

/** Phases put at most once per segment, and never backwards. */
const isTddPhase = (e: TaskEvent) => tddRank(e.phase) >= 0

/** A `brief`, `writing` or `fix` event: each one restarts TDD. */
function startsSegment(e: TaskEvent): boolean {
  return e.phase === 'brief' || e.phase === 'writing' || e.phase === 'fix'
}

/** A task's segment starts at its last segment-starting event (`-1` when none). */
function segmentStart(t: TaskState): number {
  for (let i = t.trail.length - 1; i >= 0; i--) if (startsSegment(t.trail[i]!)) return i
  return -1
}

const segmentOf = (t: TaskState) => t.trail.slice(segmentStart(t) + 1)

/** Work seen on the task: a first write gives `red`; a run after a write in the same segment gives `green`. */
function observeWork(t: TaskState, a: ActionOf<'work-observed'>): TaskState {
  const start = segmentStart(t)
  let u = t
  if (a.wrote) {
    if (!segmentOf(u).some(isTddPhase)) u = push(u, { phase: 'red', at: a.at, origin: 'observed' })
    u = { ...u, pendingWriteSegment: start }
  }
  if (a.ran && u.pendingWriteSegment === start) {
    const { pendingWriteSegment: _consumed, ...rest } = u
    const hasGreen = segmentOf(rest).some(e => e.phase === 'green' || e.phase === 'refactor')
    u = hasGreen ? rest : push(rest, { phase: 'green', at: a.at, origin: 'observed' })
  }
  return u
}

/** A reported phase confirms the one already in the segment, is dropped when backwards, or is added. */
function reportPhase(t: TaskState, phase: TddPhase, at: number): TaskState {
  const start = segmentStart(t)
  for (let i = t.trail.length - 1; i > start; i--) {
    if (t.trail[i]!.phase !== phase) continue
    return { ...t, trail: t.trail.map((e, j) => (j === i ? { ...e, origin: 'reported' as const } : e)) }
  }
  if (segmentOf(t).some(e => tddRank(e.phase) > tddRank(phase))) return t
  return push(t, { phase, at, origin: 'reported' })
}

const isReview = (e: TaskEvent) => e.phase === 'review' || e.phase === 're-review'

const hasReview = (t: TaskState) => t.trail.some(isReview)

/** The latest review or re-review was not clean and no fix has started since. */
function needsFix(t: TaskState): boolean {
  for (let i = t.trail.length - 1; i >= 0; i--) {
    const e = t.trail[i]!
    if (e.phase === 'fix') return false
    if (isReview(e)) return isUncleanVerdict(e.verdict)
  }
  return false
}

/** Sets the verdict on the latest event of `phase`, or on the one of `round` when given and present. */
function setLastVerdict(t: TaskState, phase: TaskPhase, verdict: string, round?: number): { task: TaskState; event?: TaskEvent } {
  const byRound = round !== undefined && t.trail.some(e => e.phase === phase && e.round === round)
  for (let i = t.trail.length - 1; i >= 0; i--) {
    const e = t.trail[i]!
    if (e.phase !== phase || (byRound && e.round !== round)) continue
    const event = { ...e, verdict }
    return { task: { ...t, trail: t.trail.map((x, j) => (j === i ? event : x)) }, event }
  }
  return { task: t }
}

// --- reducer ---

export function reduce(s: RunState | null, a: Action): RunState | null {
  if (a.type === 'stage-entered') return stageEntered(s, a)
  if (!s) return null
  switch (a.type) {
    case 'phase-reported': return phaseReported(s, a)
    case 'spec-written':
      return addMilestone({ ...s, specPath: a.path }, { stage: 'brainstorm', label: 'spec written', at: a.at })
    case 'plan-loaded': return planLoaded(s, a)
    case 'workspace-found': return { ...s, workspace: a.path, planPath: a.planPath }
    case 'task-started':
      return upsertTask(s, a.task, t => push(activate(t, a.at), { phase: 'brief', at: a.at }))
    case 'agent-dispatched': {
      const pending = s.agents[a.agentId]?.pendingAnswer
      const next = agentDispatched(s, a)
      return pending === undefined ? next : agentReported(next, { type: 'agent-reported', agentId: a.agentId, answer: pending, at: a.at })
    }
    case 'agent-resumed': return agentResumed(s, a)
    case 'agent-reported': return agentReported(s, a)
    case 'work-observed': return mapTask(s, a.task, t => observeWork(t, a))
    case 'task-verified':
      return upsertTask(s, a.task, t =>
        a.isOk ? finish(push(t, { phase: 'verify', at: a.at }), a.at) : push(t, { phase: 'verify', at: a.at, verdict: 'failed' }))
    case 'ledger-loaded': return ledgerLoaded(s, a)
    case 'workspace-removed':
      return s.stage === 'final-review' || s.stage === 'exec' ? { ...s, finalReview: { ...s.finalReview, phase: 'done' } } : s
    case 'branch-finished': return { ...setStage(s, 'done', a.at), finishedAt: a.at }
    case 'turn-started': {
      if (!s.waiting) return s
      const { waiting: cleared, ...rest } = s
      return s.stage === 'finishing' && cleared.reason === 'finishing-menu' ? { ...rest, isMenuAnswered: true } : rest
    }
    case 'turn-ended': return turnEnded(s, a)
  }
}

function waitFor(s: RunState): Pick<Waiting, 'reason' | 'task'> | undefined {
  switch (s.stage) {
    case 'brainstorm': return { reason: s.stagePhase === 'awaiting-approval' ? 'spec-approval' : 'brainstorm-question' }
    case 'plan': return { reason: s.tasks.length > 0 ? 'execution-choice' : 'other' }
    case 'exec': {
      const t = currentTask(s)
      if (t?.isBreakerTripped) return { reason: 'breaker', task: t.n }
      if (t?.lastStatus === 'BLOCKED') return { reason: 'blocked', task: t.n }
      return { reason: 'other' }
    }
    case 'final-review': return { reason: 'other' }
    case 'finishing': return { reason: s.isMenuAnswered ? 'other' : 'finishing-menu' }
    case 'done': return undefined
  }
}

/**
 * A main-loop turn ended: the run waits for Adrien unless a background agent is still working. In finishing, the
 * run does not end here: only a merge, push, PR, branch deletion or the keep report (`branch-finished`) ends it.
 */
function turnEnded(s: RunState, a: ActionOf<'turn-ended'>): RunState {
  const { waiting: _previous, ...rest } = s
  if (Object.values(s.agents).some(r => r.isRunning)) return rest
  const w = waitFor(s)
  return w ? { ...rest, waiting: { ...w, since: a.at } } : rest
}

/** A skill seen in a subagent only moves a run forward, and only when the agent has no worker role. */
function subagentStage(s: RunState | null, a: ActionOf<'stage-entered'>, agentId: string): RunState | null {
  if (!s || s.stage === 'done') return s
  const role = s.agents[agentId]?.role
  if ((role && WORKER_ROLES.has(role)) || rank(a.stage) < rank(s.stage)) return s
  const next = advance(s, a.stage, a.at)
  return withExecMilestone(a.mode ? { ...next, mode: a.mode } : next, a.at)
}

function stageEntered(s: RunState | null, a: ActionOf<'stage-entered'>): RunState | null {
  if (a.agentId) return subagentStage(s, a, a.agentId)
  if (!s || s.stage === 'done' || rank(a.stage) < rank(s.stage)) return withExecMilestone(newRun(a.stage, a.at, a.mode), a.at)
  const next = advance(s, a.stage, a.at)
  // A menu presented again in finishing is a new question: it waits on the person, with its notification.
  const base = s.stage === 'finishing' && a.stage === 'finishing' ? { ...next, isMenuAnswered: false } : next
  return withExecMilestone(a.mode ? { ...base, mode: a.mode } : base, a.at)
}

function phaseReported(s: RunState, a: ActionOf<'phase-reported'>): RunState {
  if (TASK_PHASES.has(a.phase)) {
    const rec = a.agentId ? s.agents[a.agentId] : undefined
    if (rec && rec.role !== 'implementer' && WORKER_ROLES.has(rec.role)) return s
    const n = rec?.role === 'implementer' && rec.task && findTask(s, rec.task) ? rec.task : currentTask(s)?.n
    return n ? mapTask(s, n, t => reportPhase(t, a.phase as TddPhase, a.at)) : s
  }
  const next = { ...s, stagePhase: a.phase }
  if (a.phase === 'builder-check') return addMilestone(next, { stage: 'brainstorm', label: 'builder check', at: a.at })
  if (a.phase === 'awaiting-approval') return addMilestone(next, { stage: 'brainstorm', label: 'spec awaiting approval', at: a.at })
  return next
}

function planLoaded(s: RunState, a: ActionOf<'plan-loaded'>): RunState {
  const tasks = a.tasks.map((p): TaskState => {
    const old = findTask(s, p.n)
    if (old && old.status !== 'todo') {
      const { runs: _old, ...kept } = old
      return { ...kept, title: p.title, steps: p.steps, ...(p.runs ? { runs: p.runs } : {}) }
    }
    return { ...p, status: 'todo', fixRounds: 0, trail: [] }
  })
  const steps = a.tasks.reduce((sum, t) => sum + t.steps, 0)
  const next = { ...(s.stage === 'brainstorm' ? setStage(s, 'plan', a.at) : s), planPath: a.path, tasks, isPlanLoaded: a.tasks.length > 0 }
  return addMilestone(
    next,
    { stage: 'plan', label: `${a.tasks.length} tasks · ${steps} steps`, at: a.at, kind: 'plan-count' },
    m => m.kind === 'plan-count',
  )
}

function agentDispatched(s: RunState, a: ActionOf<'agent-dispatched'>): RunState {
  const record = (task?: string): AgentRecord => ({
    role: a.role, isRunning: a.isRunning,
    ...(task !== undefined ? { task } : {}),
    ...(a.round !== undefined ? { round: a.round } : {}),
  })
  const n = a.task ?? currentTask(s)?.n
  switch (a.role) {
    case 'implementer':
      if (!n) return setAgent(s, a.agentId, record())
      return setAgent(upsertTask(s, n, t => {
        const active = activate(t, a.at)
        const next = hasReview(t) ? fix(active, a.at) : push(active, { phase: 'writing', at: a.at })
        return { ...next, implementerId: a.agentId }
      }), a.agentId, record(n))
    case 'reviewer':
      if (!n) return setAgent(s, a.agentId, record())
      return setAgent(upsertTask(s, n, t => push(t, { phase: 'review', at: a.at })), a.agentId, record(n))
    case 're-reviewer':
      if (!n) return setAgent(s, a.agentId, record())
      return setAgent(
        upsertTask(s, n, t => push(t, { phase: 're-review', at: a.at, round: a.round ?? t.fixRounds })),
        a.agentId, record(n))
    case 'final-reviewer':
      return setAgent({ ...advance(s, 'final-review', a.at), finalReview: { phase: 'review' } }, a.agentId, record(a.task))
    case 'builder-check': {
      const checking: RunState = s.stage === 'brainstorm' ? { ...s, stagePhase: 'builder-check' } : s
      return setAgent(addMilestone(checking, { stage: 'brainstorm', label: 'builder check', at: a.at }), a.agentId, record(a.task))
    }
    case 'other': {
      const fr = s.finalReview
      if (s.stage === 'final-review' && fr?.phase === 'review' && isUncleanVerdict(fr.verdict)) {
        return setAgent({ ...s, finalReview: { ...fr, phase: 'fixes' } }, a.agentId, record(a.task))
      }
      const cur = currentTask(s)
      if (cur && needsFix(cur)) return setAgent(mapTask(s, cur.n, t => fix(t, a.at)), a.agentId, record(cur.n))
      return setAgent(s, a.agentId, record(a.task))
    }
    case 'unknown':
      return setAgent(s, a.agentId, record(a.task))
  }
}

function agentResumed(s: RunState, a: ActionOf<'agent-resumed'>): RunState {
  const rec = s.agents[a.agentId]
  if (!rec) return s
  const next = setAgent(s, a.agentId, { ...rec, isRunning: true })
  const t = next.tasks.find(x => x.implementerId === a.agentId)
  return t && needsFix(t) ? mapTask(next, t.n, x => fix(x, a.at)) : next
}

function agentReported(s: RunState, a: ActionOf<'agent-reported'>): RunState {
  const rec = s.agents[a.agentId]
  if (!rec || rec.role === 'unknown') {
    return setAgent(s, a.agentId, { role: 'unknown', isRunning: false, pendingAnswer: a.answer })
  }
  const next = setAgent(s, a.agentId, { ...rec, isRunning: false })
  const r = parseReport(rec.role, a.answer)
  const n = rec.task
  switch (rec.role) {
    case 'implementer': {
      const status = r.status
      return status && n ? mapTask(next, n, t => ({ ...t, lastStatus: status })) : next
    }
    case 'reviewer':
    case 're-reviewer': {
      const verdict = r.verdict
      if (!verdict || !n) return next
      return mapTask(next, n, t => {
        const { task, event } = setLastVerdict(t, rec.role === 'reviewer' ? 'review' : 're-review', verdict, rec.role === 're-reviewer' ? rec.round : undefined)
        const isBreaker = rec.role === 're-reviewer' && r.isClean === false && (event?.round ?? 0) >= 5
        return isBreaker ? { ...task, isBreakerTripped: true } : task
      })
    }
    case 'final-reviewer': {
      if (!r.verdict) return next
      const phase = r.isClean ? 'done' : next.mode === 'sdd' ? 'review' : 'fixes'
      return { ...next, finalReview: { ...next.finalReview, phase, verdict: r.verdict } }
    }
    default:
      return next
  }
}

function ledgerLoaded(s: RunState, a: ActionOf<'ledger-loaded'>): RunState {
  const tasks = s.tasks.map(t => {
    let u = t
    for (const l of a.lines) {
      if (l.kind === 'complete' && l.task === t.n && u.status !== 'done') u = finish(u, a.at)
      if (l.kind === 'fix-round' && l.task === t.n && l.round > u.fixRounds) u = { ...u, fixRounds: l.round }
    }
    return u
  })
  return { ...s, tasks, decisions: decisionsOf(a.lines) }
}

