  marker('finishing.keep', 'skills/finishing-a-development-branch/SKILL.md', '3. Keep the branch as-is'),
  marker('finishing.keep.report', 'skills/finishing-a-development-branch/SKILL.md', 'Report: "Keeping branch <name>.'),
]

// --- detection ---

const SKILL_STAGES: Readonly<Record<string, { stage: Stage; mode?: Mode }>> = {
  'brainstorming': { stage: 'brainstorm' },
  'writing-plans': { stage: 'plan' },
  'subagent-driven-development': { stage: 'exec', mode: 'sdd' },
  'executing-plans': { stage: 'exec', mode: 'direct' },
  'finishing-a-development-branch': { stage: 'finishing' },
}

const REPORTED_PHASES: ReadonlySet<string> = new Set<ReportedPhase>(ALL_PHASES)

const REPORT_TOOL = 'mcp__superpowers-statusbar__report_phase'

const FINISH = /(?:^|[\s;&|(])(?:git\s+(?:-C\s+\S+\s+)?(?:merge|push|branch\s+-D)|gh\s+pr\s+create)(?=$|[\s;&|)])/

const none = (): Detection => ({ actions: [], reads: [] })
const only = (a: Action): Detection => ({ actions: [a], reads: [] })
const str = (v: unknown): string | undefined => (typeof v === 'string' ? v : undefined)
const isBeforeExec = (s: RunState) => s.stage === 'brainstorm' || s.stage === 'plan'

/**
 * The report of choice 3 (keep), as the skill words it, at the start of a sentence: English "Keeping branch …" as is,
 * French with a subject ("Je garde la branche …") or "Branche … gardée". Prose that merely mentions keeping the
 * branch ("rebased, keeping the branch history linear") is no report; nor is the French menu line "Garder la branche".
 */
const KEEP_REPORT = /^\s*(?:Keeping branch\b|(?:[Jj]e|[Oo]n|[Nn]ous)\s+(?:gard|conserv)(?:e|erai|ons|erons)\s+la\s+branche\b|[Bb]ranche(?:\s+\S+)?\s+(?:gardée|conservée))/

const NEGATION = /\b(?:not|never|ne|pas|jamais)\b|n't|\bn'/i

/** A keep report is a statement: its sentence is no question and has no negation up to the match. */
function isKeepReport(answer: string): boolean {
  return (answer.match(/[^.!?\n]+[.!?]*/g) ?? []).some(sentence => {
    const hit = KEEP_REPORT.exec(sentence)
    return !!hit && !/\?\s*$/.test(sentence.trim()) && !NEGATION.test(sentence.slice(0, hit.index + hit[0].length))
  })
}

export function detect(e: ObservedEvent, s: RunState | null): Detection {
  switch (e.kind) {
    case 'skill': return skillUsed(e.skill, e.at, e.agentId)
    case 'command': return skillUsed(e.command, e.at)
    case 'turn-start': return s ? only({ type: 'turn-started', at: e.at }) : none()
    case 'turn-end':
      if (!s) return none()
      if (e.agentId) return only({ type: 'agent-reported', agentId: e.agentId, answer: e.answer, at: e.at })
      return only(s.stage === 'finishing' && s.isMenuAnswered && isKeepReport(e.answer)
        ? { type: 'branch-finished', at: e.at }
        : { type: 'turn-ended', at: e.at })
    case 'file':
      if (!s) return none()
      return only(e.role === 'plan'
        ? { type: 'plan-loaded', path: e.path, tasks: parsePlan(e.text), at: e.at }
        : { type: 'ledger-loaded', lines: parseLedger(e.text), at: e.at })
    case 'tool': return toolUsed(e, s)
    case 'spawn': {
      // An Agent call seen first already dispatched it, with its role.
      if (s && Object.hasOwn(s.agents, e.agentId) && s.agents[e.agentId]!.role !== 'unknown') return none()
      return s ? only({ type: 'agent-dispatched', agentId: e.agentId, ...roleOf({ description: e.description, prompt: e.prompt }, s), isRunning: true, at: e.at }) : none()
    }
  }
}

function skillUsed(skill: string, at: number, agentId?: string): Detection {
  const name = skill.startsWith('superpowers:') ? skill.slice('superpowers:'.length) : skill
  const entry = Object.hasOwn(SKILL_STAGES, name) ? SKILL_STAGES[name] : undefined
  if (!entry) return none()
  return only({ type: 'stage-entered', stage: entry.stage, ...(entry.mode ? { mode: entry.mode } : {}), ...(agentId ? { agentId } : {}), at })
}

type ToolEvent = Extract<ObservedEvent, { kind: 'tool' }>

function toolUsed(e: ToolEvent, s: RunState | null): Detection {
  const d = e.tool === 'Bash' ? bashRan(e, s) : none()
  if (!s) return d
  switch (e.tool) {
    case REPORT_TOOL: {
      const phase = str(e.input.phase)
      if (phase && REPORTED_PHASES.has(phase)) {
        d.actions.push({ type: 'phase-reported', phase: phase as ReportedPhase, ...(e.agentId ? { agentId: e.agentId } : {}), at: e.at })
      }
      break
    }
    case 'Write': fileWritten(e, s, d); break
    case 'Agent': agentDispatched(e, s, d); break
    case 'SendMessage': {
      const to = str(e.input.to)
      if (to && Object.hasOwn(s.agents, to)) d.actions.push({ type: 'agent-resumed', agentId: to, at: e.at })
      break
    }
  }
  if ((e.tool === 'Write' || e.tool === 'Edit' || e.tool === 'Bash') && s.workspace && mentionsLedger(e.input)) {
    addRead(d, { role: 'ledger', path: `${s.workspace}/progress.md` })
  }
  observeWork(e, s, d)
  return d
}

// --- observed work (red / green) ---

const FILE_EDITS: ReadonlySet<string> = new Set(['Write', 'Edit', 'MultiEdit', 'NotebookEdit'])

/**
 * Whether the call ran: not refused, and either fine or failing with an exit code (a failing test run). A call
 * refused by permissions or by the shell's own checks ended in error without one.
 */
const isExecuted = (e: ToolEvent) => !e.isDenied && (!e.isError || /^Exit code \d+/.test(e.text ?? ''))

/** A write to a work file and/or a run of one of the task's plan commands, by the agent working on that task. */
function observeWork(e: ToolEvent, s: RunState, d: Detection) {
  if (s.stage !== 'exec') return
  const t = tddTask(s, e.agentId)
  if (!t) return
  let wrote = false
  let ran = false
  if (FILE_EDITS.has(e.tool)) {
    const path = str(e.input.file_path)
    wrote = !e.isError && !e.isDenied && !!path && isWorkPath(path)
  } else if (e.tool === 'Bash' && isExecuted(e)) {
    const command = str(e.input.command) ?? ''
    wrote = redirectTargets(command, t.runs ?? []).some(isWorkPath)
    ran = !isSuperpowersScript(command) && matchesPlanRun(command, t.runs ?? [])
  }
  if (wrote || ran) d.actions.push({ type: 'work-observed', task: t.n, ...(e.agentId ? { agentId: e.agentId } : {}), wrote, ran, at: e.at })
}

function addRead(d: Detection, r: FileRequest) {
  if (!d.reads.some(x => x.role === r.role && x.path === r.path)) d.reads.push(r)
}

const mentionsLedger = (input: Record<string, unknown>) =>
  Object.values(input).some(v => typeof v === 'string' && v.includes('progress.md'))

function fileWritten(e: ToolEvent, s: RunState, d: Detection) {
  const path = str(e.input.file_path)
  if (!path?.endsWith('.md')) return
  if (s.stage === 'brainstorm' && (path.includes('/specs/') || path.endsWith('-design.md'))) {
    d.actions.push({ type: 'spec-written', path, at: e.at })
    return
  }
  if (!isBeforeExec(s)) return
  const tasks = parsePlan(str(e.input.content) ?? '')
  if (tasks.length > 0) d.actions.push({ type: 'plan-loaded', path, tasks, at: e.at })
}

// --- Bash ---

const trimSlashes = (path: string) => path.replace(/\/+$/, '')

/**
 * Whether `command` is a recursive `rm` of exactly `workspace`: given in full, as a relative path the workspace
 * ends with (`.superpowers/sdd/<name>`), or as a `$VAR` / `${VAR}` assigned it earlier in the same command.
 */
export function removesWorkspace(command: string, workspace: string): boolean {
  const target = trimSlashes(workspace)
  if (!target) return false
  const vars = new Map<string, string>()
  for (const segment of command.split(/&&|\|\||[;&|\n]/)) {
    let words: string[] = segment.match(/"[^"]*"|'[^']*'|\S+/g) ?? []
    let assignment: RegExpExecArray | null
    while (words.length > 0 && (assignment = /^([A-Za-z_]\w*)=(.*)$/s.exec(words[0]!))) {
      vars.set(assignment[1]!, unquote(assignment[2]!))
      words = words.slice(1)
    }
    if (words[0] !== 'rm') continue
    let isRecursive = false
    let isOptions = true
    const paths: string[] = []
    for (const word of words.slice(1)) {
      if (isOptions && word === '--') { isOptions = false; continue }
      if (isOptions && /^-[A-Za-z]+$/.test(word)) { if (/[rR]/.test(word)) isRecursive = true; continue }
      if (isOptions && word === '--recursive') { isRecursive = true; continue }
      if (isOptions && word.startsWith('-')) continue
      paths.push(unquote(word))
    }
    if (!isRecursive || paths.length !== 1) continue
    const arg = trimSlashes(paths[0]!)
    const variable = /^\$(?:\{(\w+)\}|(\w+))$/.exec(arg)
    if (variable) {
      if (vars.get(variable[1] ?? variable[2]!) !== undefined && trimSlashes(vars.get(variable[1] ?? variable[2]!)!) === target) return true
    } else if (arg === target) return true
    else if (arg.includes('.superpowers/sdd/') && target.endsWith(`/${arg.replace(/^\.\//, '')}`)) return true
  }
  return false
}

/** Text the tool printed: `result.stdout` when the result carries one, else the rendered text. */
function outputOf(e: ToolEvent): string {
  const r = e.result
  if (r && typeof r === 'object' && 'stdout' in r && typeof r.stdout === 'string') return r.stdout
  return e.text ?? ''
}

const unquote = (arg: string) => arg.replace(/^(["'])(.*)\1$/, '$2')

/** Arguments following the script `name` (matched by basename anywhere in the command), or undefined if absent. */
function scriptArgs(command: string, name: string): string[] | undefined {
  const m = new RegExp(`(?:^|[\\s/"'(;&|=])${name}["']?(?=$|[\\s;&|)])((?:[ \\t]+[^\\s;&|)]+)*)`).exec(command)
  if (!m) return undefined
  return m[1]!.trim().split(/\s+/).filter(Boolean).map(unquote)
}

/** The output line naming a plan workspace (`…/.superpowers/sdd/<name>`), whatever else the command printed. */
function workspaceLine(text: string): string | undefined {
  return text.split(/\r?\n/).map(l => l.trim()).find(l => /(?:^|\/)\.superpowers\/sdd\/[^/\s]+\/*$/.test(l))
}

/**
 * Where to read the plan `sdd-workspace` was given: a relative path from the repository root the workspace sits in
 * (`<root>/.superpowers/sdd/<name>`), which a worktree session's cwd is not.
 */
function planFrom(plan: string, workspace: string | undefined): string {
  if (plan.startsWith('/') || !workspace) return plan
  const root = workspace.replace(/\/\.superpowers\/sdd\/[^/]+$/, '')
  return root && root !== workspace ? `${root}/${plan.replace(/^\.\//, '')}` : plan
}

function bashRan(e: ToolEvent, s: RunState | null): Detection {
  const d = none()
  const command = str(e.input.command) ?? ''
  const out = outputOf(e)
  const isOk = !e.isError

  const given = scriptArgs(command, 'sdd-workspace')?.find(a => !a.startsWith('-'))
  if (given && isOk) {
    const workspace = workspaceLine(out)?.replace(/\/+$/, '')
    const plan = planFrom(given, workspace)
    if (!s || isBeforeExec(s) || s.stage === 'done') d.actions.push({ type: 'stage-entered', stage: 'exec', at: e.at })
    if (workspace) d.actions.push({ type: 'workspace-found', path: workspace, planPath: plan, at: e.at })
    d.reads.push({ role: 'plan', path: plan })
    if (workspace) d.reads.push({ role: 'ledger', path: `${workspace}/progress.md` })
  }
  if (!s) return d

  const brief = scriptArgs(command, 'task-brief')?.[1]
  if (brief && isOk && /^wrote .+: [0-9]+ lines$/m.test(out)) d.actions.push({ type: 'task-started', task: brief, at: e.at })

  const start = scriptArgs(command, 'task-start')?.[1]
  if (start && isOk && /^brief: /m.test(out)) d.actions.push({ type: 'task-started', task: start, at: e.at })

  const done = scriptArgs(command, 'task-done')
  if (done && done.length >= 4 && done[3] === '--') {
    d.actions.push({ type: 'task-verified', task: done[1]!, isOk: isOk && out.includes('ledger: Task'), at: e.at })
  }

  if (isOk && s.workspace && removesWorkspace(command, s.workspace)) d.actions.push({ type: 'workspace-removed', at: e.at })
  if (isOk && s.stage === 'finishing' && FINISH.test(command)) d.actions.push({ type: 'branch-finished', at: e.at })
  return d
}

// --- Agent ---

type Role = { role: AgentRoleName; task?: string; round?: number }

function roleOf(input: Record<string, unknown>, s: RunState): Role {
  const description = str(input.description) ?? ''
  const prompt = (str(input.prompt) ?? '').trimStart()
  const isFinalReviewTime = s.stage === 'exec' || s.stage === 'final-review'
  let m = /^Implement Task (\S+?):?\s/.exec(description)
  if (m) return { role: 'implementer', task: m[1]! }
  m = /^Review Task (\S+) \(spec \+ quality\)/.exec(description)
  if (m) return { role: 'reviewer', task: m[1]! }
  m = /^Re-review Task (\S+) fix round (\d+)/.exec(description)
  if (m) return { role: 're-reviewer', task: m[1]!, round: Number(m[2]) }
  if (isFinalReviewTime && /^Review code changes/.test(description)) return { role: 'final-reviewer' }
  if (prompt.startsWith('You are a talented') && prompt.includes('design document')) return { role: 'builder-check' }

  const first = prompt.split('\n', 1)[0] ?? ''
  m = /^You are implementing Task (\S+?):/.exec(first)
  if (m) return { role: 'implementer', task: m[1]! }
  if (first.startsWith("You are reviewing one task's implementation")) return { role: 'reviewer' }
  if (first.startsWith("You are re-reviewing one task's fix round")) return { role: 're-reviewer' }
  if (isFinalReviewTime && first.startsWith('You are a Senior Code Reviewer')) return { role: 'final-reviewer' }
  // Real runs also word the final review their own way, in English or French: any review once every task is
  // done, except the dispatch that fixes its findings.
  const isAfterTasks = s.stage === 'final-review' || (s.stage === 'exec' && s.isPlanLoaded && s.tasks.length > 0 && s.tasks.every(t => t.status === 'done'))
  if (isAfterTasks && /(?<!\p{L})(?:review|revue)/iu.test(description) && !/\bfix|correct|corrig/i.test(description)) return { role: 'final-reviewer' }
  return { role: 'other' }
}

function agentDispatched(e: ToolEvent, s: RunState, d: Detection) {
  const r = e.result
  if (!r || typeof r !== 'object' || !('agentId' in r) || typeof r.agentId !== 'string') return
  const agentId = r.agentId
  const status = 'status' in r ? r.status : undefined
  // An agent seen at its spawn is already dispatched, with its role: the call only brings a foreground answer.
  const seen = Object.hasOwn(s.agents, agentId) && s.agents[agentId]!.role !== 'unknown'
  if (!seen) d.actions.push({ type: 'agent-dispatched', agentId, ...roleOf(e.input, s), isRunning: status === 'async_launched', at: e.at })
  if (status === 'completed') d.actions.push({ type: 'agent-reported', agentId, answer: textOf('content' in r ? r.content : undefined), at: e.at })
}

function textOf(content: unknown): string {
  if (!Array.isArray(content)) return ''
  return content
    .filter((c): c is { type: 'text'; text: string } =>
      !!c && typeof c === 'object' && c.type === 'text' && typeof c.text === 'string')
    .map(c => c.text)
    .join('\n')
}

